<script lang="ts">
 import { onMount, untrack } from 'svelte';
 import { replaceState } from '$app/navigation';
 import type { PageData } from './$types';
 import OutputReview from '#lib/modules/strategy/components/m01/OutputReview.svelte';
 import JsonEditor from '#lib/modules/strategy/components/m01/JsonEditor.svelte';
 import SourcePanel from '#lib/modules/strategy/components/m01/SourcePanel.svelte';
 import VoiceInterview from '#lib/modules/strategy/components/m01/VoiceInterview.svelte';
 let { data }: { data: PageData } = $props();
 type Anchor={key:string;sentence:string};
 type Output={status:Record<string,string>;anchorStatus:Record<string,string>;anchorNotes:Record<string,string>;outputs:{anchors:Anchor[];manifesto:string;languageBank:{category:string;phrases:string[]}[];evidenceMatrix:{claim:string;zone:string;evidence:{item:string;category:string}[]}[];claimsBoundaryInputs:{canClaim:string[];mustQualify:string[];cannotClaim:string[]}};factsAnchor:{status:string;items:{fact:string;detail:string}[]};publicRecordReadiness:{state:string;sentence:string}};
 type Session={sessionId:string;revision:number;plan:any;note:string;chat:{role:string;content:string}[];transcript:any[];outputs:Output|null;setTwoDraft:Record<string,unknown>|null;handoff:any;seal:any};
 type Snapshot={sessions:{id:string;revision:number;payload:any}[];session?:Session;stage:string|null;plan:any;note:string;chat:any[];outputs:Output|null;gates:{id:string;name:string;kind:string;result:string;detail:string}[];setTwoDraft:any;handoff:any;documents:{id:string;versionId:string;kind:string;contentHtml?:string;hash?:string}[];source:{ready:boolean;files:string[];upstreamCurrent?:boolean};upstreamCurrent?:boolean;attributions:{id:string;type:string;name:string;materialUsed:string;evidenceRefs:string[];statement:string;createdAt:string;revokedAt:string|null}[];capabilities:{voice:boolean;attestSource:boolean}};
 let initial=untrack(()=>data.initial) as Snapshot;
 let session=$state<Session|null>(initial.session??null), sessions=$state(initial.sessions??[]), snapshot=$state<Snapshot>(initial), hydrated=$state(false), busy=$state(false), pendingJob=$state<string|null>(null), message=$state('');
 let note=$state(initial.note??''), interview=$state(''), anchorNotes=$state<Record<string,string>>({}), anchorEdits=$state<Record<string,string>>({}), manifestoNote=$state(''), matrixNote=$state(''), reviewAnswers=$state<Record<string,'pass'|'fail'>>({}), sourceId=$state(''), sealNotes=$state(''), successorReason=$state('');
 let sourceType=$state('single founder / owner'), sourceName=$state(''), materialUsed=$state(''), evidenceRefs=$state<string[]>([]), statement=$state(''), revokeReason=$state('');
 let setTwo=$state<Record<string,unknown>>({});
 let voiceInterview=$state<any>(null), voiceActive=$state(false);
 let sourceStale=$derived(!snapshot.source?.ready||snapshot.upstreamCurrent===false||snapshot.source?.upstreamCurrent===false);
 let hydratedReady=$derived(hydrated && !busy && !pendingJob && !voiceActive && !sourceStale);
 let sealed=$derived(Boolean(session?.seal||session?.handoff));
 const base=()=>location.pathname;
 onMount(()=>{hydrated=true;const url=new URL(location.href);const job=url.searchParams.get('jobId');if(job)void pollJob(job);});
 const retryIds=new Map<string,string>();let pendingCreateId:string|null=null;
 function command(action:string, extra:Record<string,unknown>={}) {const body={action,sessionId:session?.sessionId,expectedRevision:session?.revision,...extra};const key=JSON.stringify(body);const commandId=retryIds.get(key)??crypto.randomUUID();retryIds.set(key,commandId);return {...body,commandId,_retryKey:key};}
 async function load(id?:string) {const url=new URL(base(),location.href);if(id)url.searchParams.set('sessionId',id);else url.searchParams.delete('sessionId');url.searchParams.delete('jobId');const response=await fetch(url,{headers:{accept:'application/json'}});const result=await response.json();if(!response.ok)throw new Error(result.error??'Unable to load session');snapshot=result;session=result.session??null;sessions=result.sessions??sessions;note=result.note??result.session?.note??'';setTwo=structuredClone(result.setTwoDraft??result.session?.setTwoDraft??{});replaceState(url,{});}
 async function post(body:Record<string,unknown>) {const response=await fetch(base(),{method:'POST',headers:{'content-type':'application/json',accept:'application/json'},body:JSON.stringify(body)});const result=await response.json();if(!response.ok)throw new Error(result.error??'Unable to save');return result;}
 async function sync(action:string,extra:Record<string,unknown>={}) {busy=true;message='';const {_retryKey,...payload}=command(action,extra);try{const result=await post(payload);if(result.jobId){retryIds.delete(String(_retryKey));return await pollJob(result.jobId);}await load(result.id??session?.sessionId);retryIds.delete(String(_retryKey));message='Saved.';return true;}catch(e){message=e instanceof Error?e.message:'Unable to save';return false;}finally{busy=false;}}
 async function pollJob(id:string):Promise<boolean> {pendingJob=id;busy=true;message='Working on your suggestion…';const url=new URL(location.href);url.searchParams.set('jobId',id);replaceState(url,{});let terminal=false;try{const until=Date.now()+90000;while(Date.now()<until){const response=await fetch(url,{headers:{accept:'application/json'}}),job=await response.json();if(!response.ok)throw new Error(job.error??'Unable to check progress');if(job.status==='succeeded'){await load(job.sessionId??session?.sessionId);message='Suggestion ready for your review.';terminal=true;return true;}if(job.status==='failed'||job.status==='cancelled'){terminal=true;const clean=new URL(location.href);clean.searchParams.delete('jobId');replaceState(clean,{});throw new Error('The suggestion did not finish. Your saved work is unchanged.');}await new Promise(r=>setTimeout(r,1800));}message='Still working. Your saved work is safe. Check progress later or return to this page to resume.';return false;}catch(e){message=e instanceof Error?e.message:'Unable to check progress';return false;}finally{if(terminal)pendingJob=null;busy=false;}}
 async function create() {busy=true;pendingCreateId??=crypto.randomUUID();try{const result=await post({action:'create',commandId:pendingCreateId});await load(result.id);pendingCreateId=null;}catch(e){message=e instanceof Error?e.message:'Unable to create session';}finally{busy=false;}}
 function setDerived(key:string,value:unknown){setTwo={...setTwo,[key]:value};}
 function readableCount(s:Session){const lines=s.transcript??[];let count=0,speaker='',buffer='';for(const line of lines){const event=line?.event;const who=event?.type==='session.input_transcript.delta'?'Founder':event?.type==='session.output_transcript.delta'?'Interviewer':'';if(!who||typeof event?.delta!=='string'){if(buffer.trim())count++;speaker='';buffer='';continue;}if(speaker&&speaker!==who){if(buffer.trim())count++;buffer='';}speaker=who;buffer+=event.delta;}if(buffer.trim())count++;return count||s.chat?.filter(line=>line.content?.trim()).length||0;}
 async function synthesiseNow(){try{await voiceInterview?.flushPending?.();await sync('synthesise');}catch(e){message=e instanceof Error?e.message:'Unable to save voice transcript';}}
 </script>

<svelte:head><title>Founder conviction</title></svelte:head>
<main class="mx-auto max-w-5xl space-y-6 p-6">
 <header class="space-y-2"><h1 class="text-2xl font-semibold">Founder conviction</h1><p>Capture the founder’s own evidence, convictions and limits. Each approval is independent and remains yours to make.</p></header>
 {#if message}<p role="status" class="rounded border p-3">{message}</p>{/if}
 {#if pendingJob}<button disabled={!hydrated||busy} onclick={()=>pollJob(pendingJob!)}>Check progress</button>{/if}
 {#if !snapshot.source?.ready||snapshot.upstreamCurrent===false||snapshot.source?.upstreamCurrent===false}<p role="alert" class="rounded border p-3">{#if snapshot.upstreamCurrent===false||snapshot.source?.upstreamCurrent===false}The approved source has changed. Refresh the engagement sources before editing or generating conviction outputs.{:else}There is no approved source material available for a new conviction session.{/if}</p>{/if}
 <section class="flex flex-wrap gap-3" aria-label="Founder conviction sessions">{#if snapshot.source?.ready&&snapshot.upstreamCurrent!==false&&snapshot.source?.upstreamCurrent!==false}<button disabled={!hydratedReady} onclick={create}>Start a conviction session</button>{/if}{#each sessions as item}<button disabled={!hydrated||busy||!!pendingJob||voiceActive} onclick={()=>{busy=true;void load(item.id).catch(e=>message=e.message).finally(()=>busy=false)}}>Open session · revision {item.revision}</button>{/each}</section>
 {#if session}
  <p>Revision {session.revision}{#if session.plan} · Interview plan ready{/if}{#if sealed} · Sealed{/if}</p>
  {#if !sealed}
   <section class="space-y-3 rounded border p-4"><h2 class="text-xl">Plan and preparation</h2><p>Prepare from the approved engagement material, or keep working in the no-plan state until you are ready.</p>{#if session.plan}<p><strong>Plan:</strong> {session.plan.summary}</p><div class="space-y-3">{#each session.plan.elements??[] as element}<article class="rounded border p-3"><h3 class="font-medium">{element.element} · {element.coverage}</h3><p>{element.feedback}</p>{#if element.evidence?.length}<p><strong>Evidence:</strong> {element.evidence.join('; ')}</p>{/if}{#if element.questions?.length}<ul>{#each element.questions as question}<li>{question}</li>{/each}</ul>{/if}</article>{/each}</div>{#if session.plan.files}<p>Source files: {session.plan.files.join(', ')}</p>{/if}{:else}<p>No interview plan has been prepared.</p>{/if}<label class="block">Preparation note<textarea class="block w-full" rows="4" bind:value={note} disabled={!hydratedReady}></textarea></label><div class="flex gap-3"><button disabled={!hydratedReady} onclick={()=>sync('note',{note})}>Save note</button>{#if !session.plan}<button disabled={!hydratedReady} onclick={()=>sync('prepare')}>Prepare interview plan</button>{/if}</div></section>
   {#if session.plan}<section class="space-y-3 rounded border p-4"><h2 class="text-xl">Founder interview</h2>{#each session.chat??[] as line}<p><strong>{line.role==='assistant'?'Interviewer':'Founder'}:</strong> {line.content}</p>{/each}<label class="block">Your response<textarea class="block w-full" rows="3" bind:value={interview} disabled={!hydratedReady}></textarea></label><button disabled={!hydratedReady} onclick={async()=>{if(await sync('turn',{message:interview.trim()||null}))interview='';}}>Send response</button>
    {#if snapshot.capabilities?.voice}{#key session.sessionId}<VoiceInterview bind:this={voiceInterview} sessionId={session.sessionId} revision={session.revision} disabled={!hydrated||sealed||Boolean(pendingJob)||busy||sourceStale} onSaved={()=>load(session?.sessionId)} onActiveChange={(active)=>voiceActive=active}/>{/key}{/if}
    <p>{readableCount(session)} readable transcript lines saved. Synthesis becomes available after at least four.</p><button disabled={!hydratedReady||voiceActive||readableCount(session)<4} onclick={synthesiseNow}>Synthesize conviction outputs</button></section>{/if}
   {#if session.outputs}<OutputReview {session} {hydratedReady} {busy} {pendingJob} {anchorNotes} {anchorEdits} {manifestoNote} {matrixNote} {reviewAnswers} onAction={(a,e)=>sync(a,e)}/>
   {/if}
   {#if session.outputs}<section class="space-y-3 rounded border p-4"><h2 class="text-xl">Set Two draft</h2><p>This draft is separate from the conviction outputs and remains editable until sealing.</p><button disabled={!hydratedReady} onclick={()=>sync('derive')}>Derive Set Two draft</button>{#if snapshot.setTwoDraft}<JsonEditor value={setTwo} onChange={setDerived} disabled={!hydratedReady}/>{/if}</section>
   <section class="space-y-3 rounded border p-4"><h2 class="text-xl">Quality review</h2><p>Review each quality gate. Every review gate must be explicitly passed before sealing.</p>{#each snapshot.gates??[] as gate}<fieldset class="rounded border p-3"><legend>{gate.name??gate.id}</legend>{#if gate.kind==='review'}<p>{gate.detail}</p><label><input type="radio" name={gate.id} value="pass" bind:group={reviewAnswers[gate.id]} disabled={!hydratedReady}/> Pass</label><label class="ml-4"><input type="radio" name={gate.id} value="fail" bind:group={reviewAnswers[gate.id]} disabled={!hydratedReady}/> Fail</label>{:else}<p><strong>Automatic check · {gate.result.replaceAll('-',' ')}</strong></p><p>{gate.detail}</p>{/if}</fieldset>{/each}</section>
   <SourcePanel {snapshot} {hydratedReady} bind:sourceType bind:sourceName bind:materialUsed bind:evidenceRefs bind:statement bind:sourceId bind:revokeReason {sync}/>
   <section class="space-y-3 rounded border p-4"><h2 class="text-xl">Seal founder conviction</h2><p>Sealing uses the named source attribution recorded above, your gate answers, and the editable Set Two draft.</p><label>Review notes<textarea class="block w-full" bind:value={sealNotes} disabled={!hydratedReady}></textarea></label><button disabled={!hydratedReady||!sourceId||!snapshot.setTwoDraft} onclick={()=>sync('seal',{reviewAnswers,derived:setTwo,sourceAttributionId:sourceId,notes:sealNotes})}>Seal approved version</button></section>{/if}
  {:else}
   <section class="space-y-4"><h2 class="text-xl">Saved founder conviction</h2>{#each snapshot.documents.filter(d=>d.kind==='founder-convictions') as document}<article class="prose max-w-none" aria-label="Saved founder conviction document" data-document-id={document.id}>{@html document.contentHtml??''}</article><p><a href={`./founder-conviction/handoff?sessionId=${session.sessionId}&versionId=${document.versionId}&documentId=${document.id}`}>Download founder conviction</a></p>{/each}</section>
   <section class="space-y-2 rounded border p-4"><h2 class="text-xl">Create a successor</h2><label>Reason<input class="ml-2" bind:value={successorReason} disabled={!hydratedReady}/></label><button disabled={!hydratedReady||!successorReason.trim()} onclick={()=>sync('successor',{reason:successorReason})}>Create successor session</button></section>
  {/if}
 {/if}
</main>

